static apollo_overlay_state s,before;
int main(void){uint16_t n,failures=0;uint8_t g;for(n=0;n<128u;++n)failures=(uint16_t)(failures+dsky_octal_consumer_checkpoint(n,&s,&before));for(g=0;g<11u;++g){p66_bias_io io,old;enum dsky_nv_mission mission;agc_word channel;enum dsky_octal_consumer_route route=(enum dsky_octal_consumer_route)3;enum dsky_octal_consumer_stage stage=DSKY_OCTAL_BEGIN;dsky_octal_consumer_input(&s,&io,0,&mission);switch(g){case 0:mission=(enum dsky_nv_mission)2;break;case 1:stage=(enum dsky_octal_consumer_stage)4;break;case 2:s.words[01001]=0;break;case 3:io.superbank=0;break;case 4:io.interrupt_enabled=2;break;case 5:s.words[5]=0;break;case 6:s.words[4]=0;break;case 7:s.words[3]=1;break;case 8:s.words[6]^=1;break;case 9:s.words[7]=1;break;default:s.words[0140]=0;break;}channel=s.words[01020];before=s;old=io;if(dsky_octal_consumer(&s,&io,mission,stage,channel,&route)!=P66_BIAS_OUT_OF_SCOPE||memcmp(&s,&before,sizeof s)||memcmp(&io,&old,sizeof io)||route!=(enum dsky_octal_consumer_route)3)++failures;}for(g=0;g<2u;++g){p66_bias_io io,old;enum dsky_nv_mission mission;enum dsky_octal_consumer_route route=DSKY_OCTAL_RECOVERY;dsky_octal_consumer_input(&s,&io,1,&mission);if(dsky_octal_consumer(&s,&io,mission,DSKY_OCTAL_BEGIN,0,&route)!=P66_BIAS_OK)return 2;s.words[g?2u:5u]=g?0100u:03416u;before=s;old=io;route=DSKY_OCTAL_RECOVERY;if(dsky_octal_consumer(&s,&io,mission,DSKY_OCTAL_FORMAT,0,&route)!=P66_BIAS_OUT_OF_SCOPE||memcmp(&s,&before,sizeof s)||memcmp(&io,&old,sizeof io)||route!=DSKY_OCTAL_RECOVERY)++failures;}printf("128 full original octal consumer stages plus13 unchanged invalid guards: %s\n",failures?"FAIL":"PASS");return failures?1:0;}
